#Creating a map

import geopandas as gpd
import matplotlib.pyplot as plt

# Load the world map data
world = gpd.read_file(gpd.datasets.get_path('naturalearth_lowres'))

# Define the countries you want to color
countries_to_color = ['China', 'India', 'United States', 'Brazil', 'Russia']

# Create a new column 'color' and set default color to light gray
world['color'] = 'lightgray'

# Color the specified countries
world.loc[world['name'].isin(countries_to_color), 'color'] = 'blue'

# Plot the world map
fig, ax = plt.subplots(1, 1, figsize=(15, 10))
world.plot(ax=ax, color=world['color'], edgecolor='k')

# Customize the plot
ax.set_title('World Map with Colored Countries')
ax.set_axis_off()

# Show the plot
plt.show()
