legend_labels = {'gray': 'Other Countries', 'blue': 'Selected Countries'} #Update this with new sets
patches = [plt.Line2D([0], [0], marker='o', color='w', 
                      markerfacecolor=color, markersize=130, label=label) for color, label in legend_labels.items()]
ax.legend(handles=patches, title='Legend', loc='lower left', fontsize=130)

