crick_bask_foot = (countries_in_cricket_world_cup & countries_in_basketball_world_cup & countries_in_football_world_cup)

foot_rest = foot_defunct - bask_defunct #All in Bask
bask_rest = bask_defunct - foot_defunct #All in Foot
