#Defunct: Soviet, Yugo, Czecho
bask_defunct = {
#     'Russia', 'Georgia', 
    'Belarus', 'Kazakhstan', 'Uzbekistan', 'Turkmenistan', 'Kyrgyzstan', 
    'Tajikistan', 'Armenia', 'Azerbaijan', 'Ukraine', 'Moldova',    #for Soviet Union 
#     'Slovenia', 'Croatia', 'Montenegro', 'Serbia'
    'Bosnia and Herzegovina', 'North Macedonia',   #for Yugoslavia
    'Slovakia' # for Czechoslavakia 
}

#Find all unique sets of countries
crick = countries_in_cricket_world_cup - countries_in_football_world_cup - countries_in_basketball_world_cup
foot = countries_in_football_world_cup - countries_in_cricket_world_cup - countries_in_basketball_world_cup #DRC
bask = countries_in_basketball_world_cup - countries_in_football_world_cup - countries_in_cricket_world_cup #SSD
crick_foot = (countries_in_cricket_world_cup & countries_in_football_world_cup) - countries_in_basketball_world_cup
bask_foot = (countries_in_basketball_world_cup & countries_in_football_world_cup) - countries_in_cricket_world_cup #CAF
crick_bask = (countries_in_cricket_world_cup & countries_in_basketball_world_cup) - countries_in_football_world_cup
crick_bask_foot = (countries_in_cricket_world_cup & countries_in_basketball_world_cup & countries_in_football_world_cup)

foot_rest = foot_defunct - bask_defunct #All in Bask
bask_rest = bask_defunct - foot_defunct #All in Foot
both_rest = bask_defunct & foot_defunct

#CREATING THE MAP
# Load the world map data
world = gpd.read_file(gpd.datasets.get_path('naturalearth_lowres'))

# Create a new column 'color' and set default color to light gray
world['color'] = 'lightgrey'

# Color the specified countries
#1 WC only
world.loc[world['name'].isin(bask), 'color'] = 'green'
world.loc[world['iso_a3']== 'SSD', 'color'] = 'green'
world.loc[world['name'].isin(foot_rest), 'color'] = 'limegreen'
world.loc[world['name'].isin(crick), 'color'] = 'dodgerblue'
world.loc[world['name'].isin(crick_ea), 'color'] = 'lightblue'
world.loc[world['name'].isin(crick_t20), 'color'] = 'navy'
world.loc[world['name'].isin(foot), 'color'] = 'coral'
world.loc[world['iso_a3']== 'COD', 'color'] = 'coral'
world.loc[world['name'].isin(bask_rest), 'color'] = 'pink'

#Countries in 2 WCs
world.loc[world['name'].isin(crick_foot), 'color'] = 'teal'
world.loc[world['name'].isin(bask_foot), 'color'] = 'darkkhaki'
world.loc[world['iso_a3'].isin({'CAF','CZE'}), 'color'] = 'darkkhaki'
# world.loc[world['iso_a3']== 'CZE', 'color'] = 'darkkhaki'
world.loc[world['name'].isin(both_rest), 'color'] = 'khaki'
world.loc[world['name'].isin(crick_bask), 'color'] = 'cyan' #No country for Old Men
#Countries in 3 WCs
world.loc[world['name'].isin(crick_bask_foot), 'color'] = 'saddlebrown'

# Plot the world map
fig, ax = plt.subplots(1, 1, figsize=(150, 200))
world.plot(ax=ax, color=world['color'], edgecolor='k')

# Customize the plot
ax.set_title('World Map with Colored Countries')
ax.set_axis_off()

# Add legend
legend_labels = {
    'gray': 'Other Countries',
    'green': 'Basketball only',
    'limegreen': 'Basketball + Defunct Football',
    'dodgerblue': 'Cricket',
    'lightblue': 'Defunct Cricket',
    'navy': 'Only T20',
    'coral': 'Football',
    'pink': 'Football + Defunct Basketball',
    'teal': 'Football + Cricket',
    'darkkhaki':'Football + Basketball',
    'khaki':'Defunct Football + Defunct Basketball',
    'saddlebrown': 'All Three'

}
patches = [plt.Line2D([0], [0], marker='o', color='w', 
                      markerfacecolor=color, markersize=90, label=label) for color, label in legend_labels.items()]
ax.legend(handles=patches, title='Legend', loc='lower left', fontsize=90)

# Show the plot
plt.show()
