all_win = 'dodgerblue'
all_win_def = 'skyblue'
all_win_06 = 'royalblue'
all_fin = 'coral'
all_fin_06 = 'orange'

# Color the specified countries
#All countries to have ever played World Cups
world.loc[world['name'].isin(all_count), 'color'] = all_c
world.loc[world['iso_a3'].isin({'CAF','SSD','DOM'}), 'color'] = all_c #Bask - Central African Rep, South Sudan and Dom Rep
world.loc[world['iso_a3'].isin({'COD','BIH'}), 'color'] = all_c #Football - Dem R of the Congo + Bosnia and Herza
#defunct countries
world.loc[world['name'].isin(crick_ea), 'color'] = all_def
world.loc[world['name'].isin(both_rest), 'color'] = all_def

#All countries since 06 + more than 2 times + not as 'defunct'
world.loc[world['name'].isin(all_count_06), 'color'] = all_06
world.loc[world['iso_a3'].isin({'CZE'}), 'color'] = all_06 #Bask + Foot -  Czech Rep. Played Bask only once

