#     all_06: 'World Cup Participant',
#     all_win_06: 'World Cup Winner',   
#     all_fin_06: 'World Cup Finalist'
# }

#Adding legend in map
patches = [plt.Line2D([0], [0], marker='o', color='w', 
                      markerfacecolor=color, markersize=90, label=label) for color, label in legend_labels.items()]
ax.legend(handles=patches, title='Legend', loc='lower left', fontsize=90)

# Show the plot
plt.show()
