#Import the needed packages
import geopandas as gpd
import matplotlib.pyplot as plt

# Load the world map data
world = gpd.read_file(gpd.datasets.get_path('naturalearth_lowres'))

# Create a new column 'color' and set default color to light gray
world['color'] = 'lightgrey'

#Color palette
all_c = 'limegreen'
all_def = 'lightgreen'
all_06 = 'green'
all_win = 'dodgerblue'
all_win_def = 'skyblue'
all_win_06 = 'royalblue'
all_fin = 'coral'
all_fin_def = 'orange'
all_fin_06 = 'darkkhaki'

# Color the specified countries
#All countries to have ever played World Cups
# world.loc[world['name'].isin(all_count), 'color'] = all_c
# world.loc[world['iso_a3'].isin({'CAF','SSD','DOM'}), 'color'] = all_c #Bask - Central African Rep, South Sudan and Dom Rep
# world.loc[world['iso_a3'].isin({'COD','BIH'}), 'color'] = all_c #Football - Dem R of the Congo + Bosnia and Herza
# #defunct countries
# world.loc[world['name'].isin(crick_ea), 'color'] = all_def
# world.loc[world['name'].isin(both_rest), 'color'] = all_def

#All countries since 06 + more than 2 times + not as 'defunct'
world.loc[world['name'].isin(all_count_06), 'color'] = all_06
world.loc[world['iso_a3'].isin({'CZE'}), 'color'] = all_06 #Bask + Foot -  Czech Rep. Played Bask only once

#All finalists and winners of all time
# world.loc[world['name'].isin(only_fin), 'color'] = all_fin
# world.loc[world['name'].isin(only_win), 'color'] = all_win #'Serbia and Montenegro', Yugo, Sov Un
# world.loc[world['name'].isin(fin_win), 'color'] = all_win #'Czechoslovakia' and Serbia is also here..
# #defunct
# world.loc[world['name'].isin(defunct_win), 'color'] = all_win_def
# world.loc[world['name'].isin(defunct_fin), 'color'] = all_fin_def

#All finalists and winners since 06
world.loc[world['name'].isin(only_fin_06), 'color'] = all_fin_06
world.loc[world['name'].isin(only_win_06), 'color'] = all_win_06 #'Serbia and Montenegro', Yugo, Sov Un
world.loc[world['name'].isin(fin_win_06), 'color'] = all_win_06

# Plot the world map
fig, ax = plt.subplots(1, 1, figsize=(150, 200))
world.plot(ax=ax, color=world['color'], edgecolor='k',linewidth=3.0)

# Customize the plot
ax.set_title('World Map with Colored Countries')
ax.set_axis_off()

# # Legend for full map
# legend_labels = {
#     'gray': 'Other Countries',
#     all_c: 'World Cup Participant',
#     all_def: 'World Cup Participant: Defunct',
#     all_06: 'World Cup Participant: Since 2006',
