#     all_fin: 'World Cup Finalist',                
#     all_fin_def: 'World Cup Finalist: Defunct',     
#     all_fin_06: 'World Cup Finalist: Since 2006'
# }

# Toggle legend for 2 individual maps
legend_labels = {
    'gray': 'Other Countries',
# #     all_c: 'World Cup Participant',
# #     all_def: 'World Cup Participant: Defunct',
# #     all_win: 'World Cup Winner',       
# #     all_win_def: 'World Cup Winner: Defunct',  
# #     all_fin: 'World Cup Finalist',             
# #     all_fin_def: 'World Cup Finalist: Defunct'
    all_06: 'World Cup Participant',
    all_win_06: 'World Cup Winner',   
    all_fin_06: 'World Cup Finalist'
}

#Adding legend in map
patches = [plt.Line2D([0], [0], marker='o', color='w', 
                      markerfacecolor=color, markersize=90, label=label) for color, label in legend_labels.items()]
ax.legend(handles=patches, title='Legend', loc='lower left', fontsize=90)

# Show the plot
