def manipulate_quarter_column(row):
    date_str = row['end_date'].strftime('%Y_%m_%d')  # Format the date string
    quarter_column_name = f'quarter_{date_str}'  # Create the column name dynamically

    if quarter_column_name in df2.columns: # Check if the column exists. Very Important
        # Access and modify the column (example: multiply by 2)
        row['Post_Uplift_{date_str}'] = row[quarter_column_name] * 2
    return row

