import pandas as pd
import numpy as np
import plotly.graph_objs as go

from datetime import date

pd.set_option('display.max_columns', None)

#Run function. put df, name of currency and run type (7 = Weekly, any other number, prefer 1 = daily)
def Run(df,name,ch):

    #Currency and dates
    df['Currency'] = name
    df['<DATE>'] = pd.to_datetime(df['<DATE>'], format='%Y.%m.%d')

    #High/Low since 2022
    df['AT_High'] = df['<CLOSE>'].max()
    df['AT_Low'] = df['<CLOSE>'].min()

    #High/Low since 52 weeks
    df['52_High'] = df['<CLOSE>'].max()
    df['52_Low'] = df['<CLOSE>'].min()
    
    #High/Low since 4 weeks
    df['1m_High'] = df['<CLOSE>'].max()
    df['1m_Low'] = df['<CLOSE>'].min()
    
    return df
###Data
