#load the data and basic analyses
import pandas as pd
import numpy as np
import plotly.graph_objs as go

from datetime import date

pd.set_option('display.max_columns', None)

#Get slope for the MAs
def numpy_slope(series, window=10):
    def calc_slope(x):
        if len(x) < window:
            return np.nan
        coeffs = np.polyfit(range(len(x)), x, 1)
        return coeffs[0]
    
    return series.rolling(window=window).apply(calc_slope)

#Run function
def Run(df,name):
    #Currency and dates
    df['Currency'] = name
    df['<DATE>'] = pd.to_datetime(df['<DATE>'], format='%Y.%m.%d')
    df.set_index('<DATE>')
    # Note these below apply to Lows and Highs
    df['1m_MA_Filter'] = 0 
    df['3m_MA_Filter'] = 0
    df['6m_MA_Filter'] = 0
    df['12m_MA_Filter'] = 0
    df['AT_MA_Filter'] = 0

    #High/Low since 1 month: 23 days or so
    df['1m_High'] = df['<CLOSE>'].rolling(window=23).max()
    df['1m_Low'] = df['<CLOSE>'].rolling(window=23).min()
    df['1m_Mean'] = df['<CLOSE>'].rolling(23).mean()
    df.loc[round(df['1m_High'],2) == round(df['<CLOSE>'],2), '1m_MA_Filter'] = 1
    df.loc[round(df['1m_Low'],2) == round(df['<CLOSE>'],2), '1m_MA_Filter'] = 1    
    df['1m_MA_slope'] = numpy_slope(df['1m_Mean'])
    df['1m_MA_slope_nm'] = (df['1m_MA_slope'] - df['1m_MA_slope'].mean()) / df['1m_MA_slope'].std()
    
    #High/Low since 3 months: 70 days or so
    df['3m_High'] = df['<CLOSE>'].rolling(window=70).max()
    df['3m_Low'] = df['<CLOSE>'].rolling(window=70).min()
    df['3m_Mean'] = df['<CLOSE>'].rolling(70).mean()
    df.loc[round(df['3m_High'],2) == round(df['<CLOSE>'],2), '3m_MA_Filter'] = 1
    df.loc[round(df['3m_Low'],2) == round(df['<CLOSE>'],2), '3m_MA_Filter'] = 1
    df['3m_MA_slope'] = numpy_slope(df['3m_Mean'])
    df['3m_MA_slope_nm'] = (df['3m_MA_slope'] - df['3m_MA_slope'].mean()) / df['3m_MA_slope'].std()
    
    #High/Low since 6 months: 135 days or so
    df['6m_High'] = df['<CLOSE>'].rolling(window=135).max()
    df['6m_Low'] = df['<CLOSE>'].rolling(window=135).min()
    df['6m_Mean'] = df['<CLOSE>'].rolling(135).mean()
    df.loc[round(df['6m_High'],2) == round(df['<CLOSE>'],2), '6m_MA_Filter'] = 1
    df.loc[round(df['6m_Low'],2) == round(df['<CLOSE>'],2), '6m_MA_Filter'] = 1
    df['6m_MA_slope'] = numpy_slope(df['6m_Mean'])
    df['6m_MA_slope_nm'] = (df['6m_MA_slope'] - df['6m_MA_slope'].mean()) / df['6m_MA_slope'].std()
    
    #High/Low since 12 months: 260 days or so
    df['12m_High'] = df['<CLOSE>'].rolling(window=260).max()
    df['12m_Low'] = df['<CLOSE>'].rolling(window=260).min()
    df['12m_Mean'] = df['<CLOSE>'].rolling(260).mean()
    df.loc[round(df['12m_High'],2) == round(df['<CLOSE>'],2), '12m_MA_Filter'] = 1
    df.loc[round(df['12m_Low'],2) == round(df['<CLOSE>'],2), '12m_MA_Filter'] = 1
    df['12m_MA_slope'] = numpy_slope(df['12m_Mean'])
    df['12m_MA_slope_nm'] = (df['12m_MA_slope'] - df['12m_MA_slope'].mean()) / df['12m_MA_slope'].std()
    # Boolean filter
    # Create a new column with 1 for 90th percentile and above, 0 otherwise
    df['MA_12m_slope_90'] = (df['12m_MA_slope_nm'] >= df['12m_MA_slope_nm'].quantile(0.95)).astype(int)
    
    #High/Low since 2022
    df['AT_High'] = df['<CLOSE>'].max()
    df['AT_Low'] = df['<CLOSE>'].min()
    df['AT_Mean'] = df['<CLOSE>'].mean()
    df['AT_Med'] = df['<CLOSE>'].median()
    df.loc[round(df['AT_High'],2) == round(df['<CLOSE>'],2), 'AT_MA_Filter'] = 1
    df.loc[round(df['AT_Low'],2) == round(df['<CLOSE>'],2), 'AT_MA_Filter'] = 1
    
    # MA Crosses: Where rounded till 3 is the same eg 0.6659 = 0.6663 = 0.666 etc
    # 1m vs 3m
    df.loc[round(df['1m_Mean'], 3) == round(df['3m_Mean'], 3), 'MA_1_3'] = 1

    # 1m vs 6m
    df.loc[round(df['1m_Mean'], 3) == round(df['6m_Mean'], 3), 'MA_1_6'] = 1

    # 1m vs 12m
    df.loc[round(df['1m_Mean'], 3) == round(df['12m_Mean'], 3), 'MA_1_12'] = 1

    # 1m vs AT
    df.loc[round(df['1m_Mean'], 3) == round(df['AT_Mean'], 3), 'MA_1_AT'] = 1

    # 3m vs 6m
    df.loc[round(df['3m_Mean'], 3) == round(df['6m_Mean'], 3), 'MA_3_6'] = 1

    # 3m vs 12m
    df.loc[round(df['3m_Mean'], 3) == round(df['12m_Mean'], 3), 'MA_3_12'] = 1

    # 3m vs AT
    df.loc[round(df['3m_Mean'], 3) == round(df['AT_Mean'], 3), 'MA_3_AT'] = 1

    # 6m vs 12m
    df.loc[round(df['6m_Mean'], 3) == round(df['12m_Mean'], 3), 'MA_6_12'] = 1

    # 6m vs AT
    df.loc[round(df['6m_Mean'], 3) == round(df['AT_Mean'], 3), 'MA_6_AT'] = 1

    # 12m vs AT
    df.loc[round(df['12m_Mean'], 3) == round(df['AT_Mean'], 3), 'MA_12_AT'] = 1

    # Optional: Fill NaN with 0 if needed
    ma_filter_columns = [
        'MA_1_3', 'MA_1_6', 'MA_1_12', 'MA_1_AT', 
        'MA_3_6', 'MA_3_12', 'MA_3_AT', 
        'MA_6_12', 'MA_6_AT', 
        'MA_12_AT'
    ]
    
    for col in ma_filter_columns:
        df[col] = df[col].fillna(0)

    
    return df
###Data
df = pd.read_csv (r'C:\Users\nitis\Documents\Forex\Data\New data\AUDUSD.csv',sep='\t')
df2 = Run(df,'AUDUSD')
df2.tail()
