# Analysis on the datasets
base_path_hist = r"C:\Users\nitis\Documents\Forex\Data\New data\Hist data"
#  store non-empty dfs
collected_st = []
collected_wk = []

#Loop through all currencies, len(daily)
for i in range(0,len(Curr)):
    path = fr"{base_path_hist}\{Curr[i]}.csv"
    df = pd.read_csv(path, sep=r'[,\\t]', engine='python')
    print(df)
    df2 = Run(df,Curr[i])
    df2 = df2.tail()

    # Strong set: 4 filters
    # - Close is near AT and/or 12m H/L then time could be to reverse - Strong
    # - Rolling MA crosses comparisons for 12 with various and AT
    df_st = Filter(df2, ['AT_MA_Filter', '12m_MA_Filter'
                        ,'MA_6_AT','MA_12_AT'])
    
    df_st = df_st [['<DATE>', 'Currency', 'Total_Filters']]
    df_st = df_st.drop_duplicates(subset=['Currency', 'Total_Filters'])
    
    # Weak set: 11 filters
    # - Close is near other H/L then time could be to reverse - Weak
    # - Rolling MA crosses comparisons for 1 with various and 3/6
    # - Slopes for sudden jumps
    df_wk = Filter(df2, ['1m_MA_Filter','3m_MA_Filter','6m_MA_Filter'
                         ,'MA_1_3', 'MA_1_6', 'MA_1_12', 'MA_1_AT','MA_3_6'
                        ,'1m_slope','3m_slope','6m_slope'])
    
    df_wk = df_wk [['<DATE>', 'Currency', 'Total_Filters']]   
    df_wk = df_wk.drop_duplicates(subset=['Currency', 'Total_Filters'])

    #Collect data in one set
    if not df_st.empty:
        collected_st.append(df_st)

    if not df_wk.empty:
        collected_wk.append(df_wk)

if collected_st:
    result_st = pd.concat( collected_st, ignore_index=True)
else:
    result_st = pd.DataFrame()  # empty result

if collected_wk:
    result_wk = pd.concat(collected_wk, ignore_index=True)
else:
    result_wk = pd.DataFrame()  # empty result

print(result_st)
print(result_wk)
