for a, b in itertools.combinations(symbols, 2):
    L = dfs[a]
    R = dfs[b]
    
    # union of dates, then reindex both
    common_index = left.index.union(right.index)
    L = left.reindex(common_index)
    R = right.reindex(common_index)

    # elementwise division for the four columns (a / b -> base/quote)
    cross_df = L[cols].divide(R[cols])

    base = a.replace("USD", "")
    quote = b.replace("USD", "")
    cross_name = f"{base}{quote}"

    # reset <DATE> as column and keep exact column order
    cross_df = cross_df.reset_index().rename_axis(None)
    cross_df = cross_df.loc[:, ["<DATE>"] + cols]

    result[cross_name] = cross_df

