def df_div(symbols, base_path):
    #Step 1: Create and save the data
    for sym in symbols:
        path = fr"{base_path}\{sym}.csv"
        df = pd.read_csv(path, sep='\t')
        # ensure required columns
        required = ["<DATE>","<OPEN>","<HIGH>","<LOW>","<CLOSE>"]
        # normalize
        df = df.copy()
        df["<DATE>"] = pd.to_datetime(df["<DATE>"])
