import pickle
import sys
import numpy.random

# 1. Define a custom Unpickler to catch and redirect the bad reference
class CompatibilityUnpickler(pickle.Unpickler):
    def find_class(self, module, name):
        # If pickle looks for the old numpy random path, redirect it
        if module == 'numpy.random._pcg64' and name == 'PCG64':
            return numpy.random.PCG64
        return super().find_class(module, name)

# 2. Open and load the file using our custom unpickler
