# Custom unpickler to catch the object's state and fix it on the fly
class StateFixerUnpickler(pickle.Unpickler):
    def find_class(self, module, name):
        obj = super().find_class(module, name)
        
        # If the object has a __setstate__ method that is failing, 
        # we can wrap it or inspect what it's trying to pass.
        return obj

file_path = 'H:/Work/Hotspotting/ppi/PPI2/ppi_v4_1_model.pkl'

