    try:
        data = StateFixerUnpickler(file).load()
        print("🎉 Success! Object type is:", type(data))
    except TypeError as e:
        print(f"Caught expected error: {e}")
        print("\nLet's extract the raw data without initializing the broken object:")
        
        # Rewind file and extract the raw tuple/state structure
        file.seek(0)
        import pickletools
        # Print the last few structural pieces to see what class is breaking
        for op, arg, pos in list(pickletools.genops(file))[-20:]:
            print(f"Op: {op.name}, Arg: {arg}")
