import string

file_path = 'H:/Work/Hotspotting/ppi/PPI2/ppi_v4_1_model.pkl'

printable_chars = set(string.printable)
current_string = []
strings_found = []

# Read the file as raw bytes
with open(file_path, 'rb') as f:
    for byte in f.read():
        char = chr(byte)
        if char in printable_chars and byte >= 32 and byte <= 126:
            current_string.append(char)
        else:
            if len(current_string) >= 4:  # Only keep readable text longer than 4 characters
                strings_found.append("".join(current_string))
            current_string = []

# Print the first 60 text strings found in the file
print(f"--- Found {len(strings_found)} text entries. Showing the first 60: --- \n")
for s in strings_found[:60]:
    print(s)
