symbols = ["XAGUSD.a","XAUUSD.a", 
          "EURUSD", "GBPUSD", "AUDUSD", "NZDUSD",
          "USDCAD", "USDCHF", "USDJPY", "USDMXN", "USDSGD"]
res2 = {} #Define the dict
res2 = df_div(symbols)
