# 2. Load the data fromt the loop
filtered_df = pd.DataFrame({'Currency': ['USDJPY', 'EURUSD', 'AUDUSD','US30.a']})
    
# 2. Loop through the unique currencies in the filtered DataFrame
for currency in filtered_df['Currency']:
    # Ensure we handle any potential missing/NaN values safely
    if pd.isna(currency):
        continue
        
    # Construct the file path using an f-string
    file_path = fr"C:\Users\nitis\Documents\Forex\Data\New data\{currency}.csv"
    
    print(f"Loading data for: {currency}")
    
    # Read the CSV file
    df_mod = pd.read_csv(file_path, sep='\t', engine='python')

    # --- RUN THE TUNED BACKTEST ---
    # train_window=250 means the model looks at roughly 1 year of daily history to learn patterns
    # test_steps=50 means it will simulate trading for the last 50 consecutive market sessions
    # Unpacking all 6 elements cleanly to handle risk management additions without ValueError crashing
    (
        processed_df, 
        historical_accuracy, 
        historical_sharpe, 
        historical_sortino, 
        historical_max_dd, 
        ranked_features
    ) = run_walk_forward_validation_tuned(
        df=df_mod, 
        train_window=250, 
        test_steps=50
    )

    print("\n" + "="*50)
    print("           TUNED BACKTEST RESULTS                 ")
    print("==================================================")
    print(f"Adaptive Directional Accuracy: {historical_accuracy:.2%}")
    print("==================================================")
    print(f"Adaptive Sharpe Ratio:         {historical_sharpe:.2f}") 
    print("==================================================")
    print(f"Adaptive Sortino Ratio:        {historical_sortino:.2f}") 
    print("==================================================")
    print(f"Max Peak-to-Trough Drawdown:   {historical_max_dd:.2%}") 
    print("==================================================")
