import pandas as pd
import warnings

# IMPORT VALUEWARNING SO PYTHON RECOGNIZES IT
from statsmodels.tools.sm_exceptions import ValueWarning

# 1. Force Python to silence the specific statsmodels base warnings
warnings.filterwarnings("ignore", category=ValueWarning, module="statsmodels")
warnings.filterwarnings("ignore", category=FutureWarning, module="statsmodels")
warnings.filterwarnings("ignore", message=".*No supported index is available.*")

# 2. Load the target cross-currency matrix
filtered_df = pd.DataFrame({'Currency': ['USDJPY', 'EURUSD', 'AUDUSD', 'US30.a']})
    
# 3. Loop through the unique currencies in the filtered DataFrame
for currency in filtered_df['Currency']:
    if pd.isna(currency):
        continue
        
    # Construct paths matching your local directory architecture
    file_path = fr"C:\Users\nitis\Documents\Forex\Data\New data\{currency}.csv"
    file_path_h4 = fr"C:\Users\nitis\Documents\Forex\Data\New data\{currency}_h4.csv"
    
    print(f"\n" + "=" * 115)
    print(f" INITIALIZING PARALLEL DUAL-STRATEGY PIPELINE FOR: {currency} ")
    print("=" * 115)
    
    # Read the historical data streams
    df_mod = pd.read_csv(file_path, sep='\t', engine='python')
    df_mod_h4 = pd.read_csv(file_path_h4, sep='\t', engine='python')

    # Guard clause: Ensure history depth satisfies structural test boundaries
    if len(df_mod) < 800:
        print(f"Skipping {currency}: Historical dataset size ({len(df_mod)} rows) insufficient for stress testing.")
        continue

    print("Running historical backtest simulations on raw data...")
    
    # --- RUN BASELINE WALK-FORWARD BACKTEST FOR ACCOUNTING ---
    (
        mae_rev, 
        sharpe_rev, 
        mae_mom, 
        sharpe_mom, 
        max_dd_comb, 
        ranked_features
    ) = run_block_walk_forward_validation(
        df_daily=df_mod,
        df_h4=df_mod_h4, 
        train_window=700,
        retrain_interval=100
    )

    # --- PRINT BASELINE TECHNICAL FEATURE IMPACT RANKINGS USING DICTIONARY LOOKUP ---
    print(f"\n[BASELINE REVERSION FEATURE RANKINGS FOR {currency}]:")
    print("-" * 135)
    print(f"{'Rank':<5} | {'Feature Column Name':<25} | {'Relative Impact':<15} | {'Functional Dictionary Definition'}")
    print("-" * 135)
    
    # Merge definitions for visualization purposes in the leaderboard
    combined_encyclopedia = {**MEAN_REVERSION_FEATURES, **PURE_MOMENTUM_FEATURES}
    
    for rank, (feature, importance) in enumerate(ranked_features[:10], 1):
         feature_definition = combined_encyclopedia.get(feature, "Derived engine feature column.")
         print(f"Rank {rank:02d} | {feature:<25} | {importance:>14.2f}% | {feature_definition}")
    print("-" * 135)

    # --- GENERATE MULTI-ENGINE INTRADAY DEVELOPMENT SCENARIOS FOR TOMORROW ---
    # This invokes the updated 6-scenario decision rubric matrix and automatically
    # cascades into the robust 4-flavor synthetic stress backtest comparison suites.
    predict_next_day_scenarios(df_mod, df_mod_h4, train_window=700)
