    df_fin['St_Filters'] = df_fin['St_Filters'].fillna(0).astype(int)
    df_fin['Wk_Filters'] = df_fin['Wk_Filters'].fillna(0).astype(int)
    df_fin['<CLOSE>'] = df_fin['<CLOSE>'].fillna(df_fin['<CLOSE>_x'])
    df_fin['AT_Low'] = df_fin['AT_Low'].fillna(df_fin['AT_Low_x'])
    df_fin['AT_High'] = df_fin['AT_High'].fillna(df_fin['AT_High_x'])
    df_fin['Close_check'] = df_fin['Close_check'].fillna(df_fin['Close_check_x'])

    # Drop intermediate duplicate workspace columns
    drop_cols = ['Direction_x', 'Direction_y', 'Momentum_x', 'Momentum_y', '<CLOSE>_x', 'AT_Low_x', 'AT_High_x', 'Close_check_x']
    df_fin.drop(columns=[c for c in drop_cols if c in df_fin.columns], inplace=True)

    # Prioritize execution rows by signal weights
    df_fin = df_fin.sort_values(by=['St_Filters', 'Wk_Filters'], ascending=False).reset_index(drop=True)
