import numpy as np
import pandas as pd
from fredapi import Fred

# 1. Initialize FRED API Connection
# Replace with your actual FRED API key or set it as an environment variable
FRED_API_KEY = "1f3befec93b6c68383d27f3b58cca038"
fred = Fred(api_key=FRED_API_KEY)

# 2. Map structural components to live FRED Series IDs
series_map = {
    "USD": {
        "Nominal_Rate": "FEDFUNDS",
        "Inflation": "CPILFESL",  # Core CPI
        "GDP_Growth": "A191RL1Q225SBEA",  # Real GDP Annual % Change
    },
    "EUR": {
        "Nominal_Rate": "ECBDFR",  # ECB Deposit Rate
        "Inflation": "CP0000EZ19M086NEST",  # Harmonized CPI Euro Area
        "GDP_Growth": "CLVMNACSCAB1GQEU27",  # We will calculate % change dynamically
    },
    "GBP": {
        "Nominal_Rate": "IUMABEDR",  # BoE Bank Rate
        "Inflation": "GBRCPIALLMINMEI",  # UK CPI
        "GDP_Growth": "UKNGDPRPCHGQS",  # UK Real GDP YoY % Change
    },
    "JPY": {
        "Nominal_Rate": "INTDSRJPM193N",  # BoJ Policy Rate proxy
        "Inflation": "JPNCPIALLMINMEI",  # Japan CPI
        "GDP_Growth": "JPNRGDPDPCHQS",  # Japan Real GDP YoY % Change
    },
}


def fetch_latest_macro_data():
    raw_snapshot = {}

    for currency, metrics in series_map.items():
        raw_snapshot[currency] = {}
        for metric_name, series_id in metrics.items():
            try:
                # Fetch full historical series from FRED
                series_data = fred.get_series(series_id)
                # Drop NaNs and grab the absolute freshest data point released
                series_clean = series_data.dropna()

                # Process raw indexes into percentage changes if needed
                if (
                    metric_name == "Inflation"
                    and currency in ["EUR", "GBP", "JPY"]
                ):
                    # For raw CPI indexes, calculate the YoY % change over the last 12 months
                    pct_change = series_clean.pct_change(periods=12) * 100
                    latest_val = pct_change.iloc[-1]
                elif metric_name == "GDP_Growth" and currency == "EUR":
                    # For raw EU GDP volume index, calculate YoY quarterly % change
                    pct_change = series_clean.pct_change(periods=4) * 100
                    latest_val = pct_change.iloc[-1]
                else:
                    # Otherwise, it's already a percentage rate (e.g. Fed Funds Rate)
                    latest_val = series_clean.iloc[-1]

                raw_snapshot[currency][metric_name] = latest_val

            except Exception as e:
                print(f"Error fetching {metric_name} ({series_id}) for {currency}: {e}")
                raw_snapshot[currency][metric_name] = np.nan

    # Convert to Dataframe
    df = pd.DataFrame.from_dict(raw_snapshot, orient="index")

    # Add hardcoded structural parameters that APIs don't track well (Terms of Trade Energy insulation)
    # Energy Insulation scale: US (+2.0), UK (-0.5), Japan (-1.5), Eurozone (-2.0)
    df["Energy_Insulation"] = [2.0, -2.0, -0.5, -1.5]

    # Calculate live Real Yields
    df["Real_Yield"] = df["Nominal_Rate"] - df["Inflation"]

    return df


def generate_live_fx_scorecard(df):
    z_scored_df = pd.DataFrame(index=df.index)

    # Standardize data via Z-scores relative to peer group
    features_to_score = ["Real_Yield", "GDP_Growth", "Energy_Insulation"]
    for col in features_to_score:
        mean = df[col].mean()
        std = df[col].std()
        z_scored_df[f"Z_{col}"] = (df[col] - mean) / std

    # Apply macro weights
    weights = {
        "Z_Real_Yield": 0.40,
        "Z_GDP_Growth": 0.30,
        "Z_Energy_Insulation": 0.30,
    }

    z_scored_df["Structural_Score"] = 0.0
    for feature, weight in weights.items():
        z_scored_df["Structural_Score"] += z_scored_df[feature] * weight

    return z_scored_df.sort_values(by="Structural_Score", ascending=False)


# Run Pipeline
try:
    live_macro_df = fetch_latest_macro_data()
    scorecard_df = generate_live_fx_scorecard(live_macro_df)

    print("\n====== LIVE ECONOMIC DATA INGESTED FROM FRED ======")
    print(live_macro_df[["Nominal_Rate", "Inflation", "Real_Yield", "GDP_Growth"]].round(2))

    print("\n====== AUTOMATED FX SCORECARD (DIRECTIONAL BIAS) ======")
    print(scorecard_df.round(3))

except ValueError:
    print("Please insert a valid FRED API key to run live data updates.")
