import numpy as np
import pandas as pd
from fredapi import Fred
import sys

# =====================================================================
# ENGINE INITIALIZATION
# =====================================================================
FRED_API_KEY = "YOUR_FREE_FRED_API_KEY_HERE"

if FRED_API_KEY == "YOUR_FREE_FRED_API_KEY_HERE" or not FRED_API_KEY:
    print("\n[!] ERROR: Valid FRED API Key required for hybrid matrix execution.")
    sys.exit()

fred = Fred(api_key=FRED_API_KEY)

# Global 9-Currency Asset Matrix
series_map = {
    "USD": {"Nominal_2Y": "GS2", "Inflation": "CPIAUCSL", "GDP_Growth": "A191RL1Q225SBEA", "Terms_of_Trade": "NETEXP", "Current_Account": "IEABC"},
    "EUR": {"Nominal_2Y": "ECBDFR", "Inflation": "CP0000EZ19M086NEST", "GDP_Growth": "CLVMEURSCAB1GQEU272020", "Terms_of_Trade": "NETEXPEL", "Current_Account": "IEABCEU"},
    "GBP": {"Nominal_2Y": "STLPBLGBA188N", "Inflation": "GBRCPIALLMINMEI", "GDP_Growth": "UKNGDPRPCHGQS", "Terms_of_Trade": "NETEXPGB", "Current_Account": "IEABCGB"},
    "JPY": {"Nominal_2Y": "INTDSRJPM193N", "Inflation": "JPNCPIALLMINMEI", "GDP_Growth": "JPNRGDPDPCHQS", "Terms_of_Trade": "NETEXPJP", "Current_Account": "IEABCJP"},
    "INR": {"Nominal_2Y": "INDIR3M", "Inflation": "INDCPIALLMINMEI", "GDP_Growth": "INDNGDPRPCHGQS", "Terms_of_Trade": "NETEXPIN", "Current_Account": "IEABCIN"},
    "AUD": {"Nominal_2Y": "IR3MTIBBA01STM", "Inflation": "AUSCPIALLMINMEI", "GDP_Growth": "AUSNGDPRPCHGQS", "Terms_of_Trade": "NETEXPAU", "Current_Account": "IEABCAU"},
    "CAD": {"Nominal_2Y": "IR3MTIBCA01STM", "Inflation": "CANCPIALLMINMEI", "GDP_Growth": "NGDPRSAXDCADB", "Terms_of_Trade": "NETEXPCA", "Current_Account": "IEABCCA"},
    "CHF": {"Nominal_2Y": "INTDSRCHM193N", "Inflation": "CHECPIALLMINMEI", "GDP_Growth": "CHEUETHGQS", "Terms_of_Trade": "NETEXPCH", "Current_Account": "IEABCCH"},
    "CNY": {"Nominal_2Y": "INTDSRCNM193N", "Inflation": "CPALTT01CNM657N", "GDP_Growth": "Daily_Data_Fallback", "Terms_of_Trade": "NETEXPCN", "Current_Account": "IEABCCN"}
}

# 2026 Baseline Reference Bank (Used as inputs for Method C if Live Data fails)
fallback_defaults = {
    "USD": {"Nominal_2Y": 3.65, "Inflation": 4.1, "GDP_Growth": 2.0, "Terms_of_Trade": 50.0, "Current_Account": -200.0},
    "EUR": {"Nominal_2Y": 2.10, "Inflation": 3.1, "GDP_Growth": 1.0, "Terms_of_Trade": -20.0, "Current_Account": 40.0},
    "GBP": {"Nominal_2Y": 3.80, "Inflation": 3.4, "GDP_Growth": 1.1, "Terms_of_Trade": -15.0, "Current_Account": -10.0},
    "JPY": {"Nominal_2Y": 0.45, "Inflation": 2.1, "GDP_Growth": 0.5, "Terms_of_Trade": -30.0, "Current_Account": 20.0},
    "INR": {"Nominal_2Y": 6.80, "Inflation": 4.8, "GDP_Growth": 6.5, "Terms_of_Trade": -40.0, "Current_Account": -15.0},
    "AUD": {"Nominal_2Y": 4.40, "Inflation": 3.6, "GDP_Growth": 1.5, "Terms_of_Trade": 25.0, "Current_Account": 5.0},
    "CAD": {"Nominal_2Y": 3.55, "Inflation": 2.8, "GDP_Growth": 1.4, "Terms_of_Trade": 15.0, "Current_Account": -2.0},
    "CHF": {"Nominal_2Y": 1.25, "Inflation": 1.2, "GDP_Growth": 1.3, "Terms_of_Trade": 35.0, "Current_Account": 75.0},
    "CNY": {"Nominal_2Y": 2.10, "Inflation": 1.2, "GDP_Growth": 4.5, "Terms_of_Trade": 65.0, "Current_Account": 80.0}
}

# =====================================================================
# ENGINE C: DYNAMIC DISTANCE-TO-POLICY TARGET ALGORITHM
# =====================================================================
def calculate_method_c_score(currency, metric_name, val):
    """Standardizes metrics relative to economic mandates/targets (Scale: 0.0 to 1.0)"""
    if metric_name == "Inflation":
        # Global Central Bank Target Mandate = 2.0%. Penalize deviations.
        distance = abs(val - 2.0)
        return max(0.0, min(1.0, 1.0 - (distance * 0.15)))
    
    elif metric_name == "GDP_Growth":
        # Differentiate growth targets between Emerging Markets (5%) and Developed Markets (2%)
        target = 5.0 if currency in ["INR", "CNY"] else 2.0
        return max(0.0, min(1.0, 0.5 + (val - target) * 0.15))
    
    elif metric_name == "Nominal_2Y":
        # Reward yield buffer capacity up to a 6.0% global ceiling
        return max(0.0, min(1.0, val / 6.0))
    
    elif metric_name in ["Terms_of_Trade", "Current_Account"]:
        # Soft-clipping trade balance parameters around a zero-axis equilibrium line
        return max(0.0, min(1.0, 0.5 + (val / 150.0)))
        
    return 0.5

# =====================================================================
# DUAL-ENGINE INGESTION PIPELINE
# =====================================================================
def fetch_hybrid_macro_scorecard():
    live_values = {}
    standardized_scores = {}
    engine_log = {}
    
    start_date = "2021-01-01"

    for currency, metrics in series_map.items():
        live_values[currency] = {}
        standardized_scores[currency] = {}
        engine_log[currency] = {}
        
        for metric_name, series_id in metrics.items():
            try:
                # Attempt to pull historical vector from FRED
                if currency == "CAD" and metric_name == "GDP_Growth":
                    series_hist = fred.get_series("NGDPRSAXDCADB", start_date=start_date).dropna()
                    history = (series_hist.pct_change(periods=4) * 100).dropna()
                elif series_id == "Daily_Data_Fallback":
                    raise ValueError()
                else:
                    series_hist = fred.get_series(series_id, start_date=start_date).dropna()
                
                if metric_name == "Inflation":
                    history = (series_hist.pct_change(periods=12) * 100).dropna()
                elif currency == "EUR" and metric_name == "GDP_Growth":
                    history = (series_hist.pct_change(periods=4) * 100).dropna()
                else:
                    history = series_hist

                if len(history) == 0:
                    raise ValueError()

                latest_val = history.iloc[-1]
                live_values[currency][metric_name] = latest_val

                # ENGINE A EXECUTION: Historical Percentile Ranking
                if metric_name == "Inflation":
                    rank = (history >= latest_val).sum() / len(history)
                else:
                    rank = (history <= latest_val).sum() / len(history)
                
                standardized_scores[currency][f"S_{metric_name}"] = rank
                engine_log[currency][metric_name] = "ENG_A [HIST_PCT]"

            except Exception:
                # ENGINE C INTERCEPT: Process baseline via distance-to-policy mapping
                fallback_val = fallback_defaults[currency][metric_name]
                live_values[currency][metric_name] = fallback_val
                
                policy_score = calculate_method_c_score(currency, metric_name, fallback_val)
                standardized_scores[currency][f"S_{metric_name}"] = policy_score
                engine_log[currency][metric_name] = "ENG_C [TARGET]"

    df_values = pd.DataFrame.from_dict(live_values, orient="index")
    df_values["Real_2Y_Yield"] = df_values["Nominal_2Y"] - df_values["Inflation"]
    
    df_scores = pd.DataFrame.from_dict(standardized_scores, orient="index")
    df_engines = pd.DataFrame.from_dict(engine_log, orient="index")
    
    # Portfolio Allocation Weight Protocol
    weights = {
        "S_Nominal_2Y": 0.35,
        "S_GDP_Growth": 0.25,
        "S_Terms_of_Trade": 0.25,
        "S_Current_Account": 0.15
    }
    
    df_scores["Structural_Score"] = 0.0
    for feature, weight in weights.items():
        df_scores["Structural_Score"] += df_scores[feature] * weight
        
    return df_values, df_scores.sort_values(by="Structural_Score", ascending=False), df_engines

# =====================================================================
# RUN PORTFOLIO MATRIX
# =====================================================================
if __name__ == "__main__":
    val_df, score_df, log_df = fetch_hybrid_macro_scorecard()

    print("\n" + "=" * 95)
    print(" HYBRID CAPTURE ROUTING LOG: CONFIRMING ACTIVE PROCESSING NODES ")
    print("=" * 95)
    print(log_df)

    print("\n" + "=" * 95)
    print(" CONSOLIDATED MACRO INPUT METRICS ")
    print("=" * 95)
    print(val_df[["Nominal_2Y", "Inflation", "Real_2Y_Yield", "GDP_Growth", "Terms_of_Trade", "Current_Account"]].round(2))

    print("\n" + "=" * 95)
    print(" COMBINED SYSTEM STANDARDIZED LEADERBOARD (ENG_A + ENG_C BLENDED) ")
    print("=" * 95)
    print(score_df[["S_Nominal_2Y", "S_GDP_Growth", "S_Terms_of_Trade", "S_Current_Account", "Structural_Score"]].round(3))
    print("=" * 95)
