# --- Enhanced Execution Loop ---
collected_st = []
collected_wk = []
adf_results = []

# Combine underlying and cross-currency asset dictionaries
fin_res = res1 | res2

#Mean-reverson tests
from statsmodels.tsa.stattools import adfuller
from hurst import compute_Hc
import matplotlib.pyplot as plt
    
for name, df in fin_res.items():
    #For strong and weak indicators
    df_st,df_wk = analyse(name, df)
    if not df_st.empty:
        collected_st.append(df_st)
    if not df_wk.empty:
        collected_wk.append(df_wk)
    # Tests - 
    # ADF to check Stationary or not + 
    # Hurst (x3), and MFDFA to test if mean-reversion (values less than 0.5) or trending (higher values)
    # Price close data selection
    series = df['<CLOSE>'].dropna()
    series = series[np.isfinite(series)] 
    
    #Skip if too little data
    if len(series) < 50:
        print(f"Skipping {name}: Insufficient data points ({len(series)})")
        continue
    
    #Filtering 0s
    series_values = series.values

    # Keep only values that are strictly greater than (or not equal to) zero
    series_values = series_values[series_values != 0]

    with np.errstate(divide='ignore', invalid='ignore'):
        result = adfuller(series, autolag='AIC')
#         calc_h, calc_rsq_h = calculate_hurst(series_values)
        avg_h, std_h = utils.rolling_hurst(series_values)
#         h_val = get_hurst(series[series != 0])
        mfdfa_val = get_MFDFA(series_values)
        
    # Add the data into one place to join later
    #Hurst:<0.5 means high->low; > means high->high. 
    #MFDFA: Monofractal is more trustworthy, multifractal width may have some fakeouts too  
    adf_results.append({
        'Currency': name,
        'ADF_pvalue': result[1],
        'ADF_Statistic': result[0],
#         'Hurst': h_val,
        'MFDFA': mfdfa_val,
#         'calc_h': calc_h,
        'avg_h': avg_h,
        'std_h': std_h
    })
        
# Convert statistical matrices to a unified summary frame
adf_results = pd.DataFrame(adf_results)

# Safety checks for empty collection frames
result_st = pd.concat(collected_st, ignore_index=True) if collected_st else pd.DataFrame()
result_wk = pd.concat(collected_wk, ignore_index=True) if collected_wk else pd.DataFrame()

# 4. Consolidate Strong, Weak, and Statistical Frames Cleanly
df_fin_0 = result_st.merge(result_wk, on='Currency', how='outer')
df_fin = df_fin_0.merge(adf_results, on='Currency', how='outer')

# 5. Strategic Column Collapse & Metadata Sorting
# Map out the new Direction and Momentum layers cleanly across missing slots
if not df_fin.empty:
    df_fin['Direction'] = df_fin['Direction_x'].fillna(df_fin['Direction_y'])
    df_fin['Momentum'] = df_fin['Momentum_x'].fillna(df_fin['Momentum_y'])
    
    # Structural column cleanup and alignment matching your layout schema
    df_fin.rename(columns={
        'Total_Filters_x': 'St_Filters',
        'Total_Filters_y': 'Wk_Filters',
        'AT_Low_y': 'AT_Low',
        'AT_High_y': 'AT_High',
        '<CLOSE>_y': '<CLOSE>',
        'Close_check_y': 'Close_check'
    }, inplace=True)
    
    # Fill structural gaps for assets that only registered one set
    df_fin['St_Filters'] = df_fin['St_Filters'].fillna(0).astype(int)
    df_fin['Wk_Filters'] = df_fin['Wk_Filters'].fillna(0).astype(int)
    df_fin['<CLOSE>'] = df_fin['<CLOSE>'].fillna(df_fin['<CLOSE>_x'])
    df_fin['AT_Low'] = df_fin['AT_Low'].fillna(df_fin['AT_Low_x'])
    df_fin['AT_High'] = df_fin['AT_High'].fillna(df_fin['AT_High_x'])
    df_fin['Close_check'] = df_fin['Close_check'].fillna(df_fin['Close_check_x'])

    # Drop intermediate duplicate workspace columns
