import pandas as pd
from fredapi import Fred
from datetime import datetime

class FredDataSearcher:
    def __init__(self, api_key: str):
        """Initializes the FRED search engine."""
        self.fred = Fred(api_key=api_key)
        
    def find_tickers(self, keyword: str, country: str = None, limit: int = 15) -> pd.DataFrame:
        """
        Advanced search tool to locate active, non-discontinued FRED tickers.
        
        Parameters:
            keyword (str): The economic indicator (e.g., 'interest rate', 'gdp', 'cpi')
            country (str): Optional country filter (e.g., 'Japan', 'United Kingdom', 'Euro Area')
            limit (int): Number of top popular results to return
        """
        print(f"🔍 Searching FRED for '{keyword}'" + (f" within '{country}'..." if country else "..."))
        
        try:
            # Combine text search parameters
            search_query = keyword
            if country:
                search_query = f"{country} {keyword}"
                
            # Perform programmatic text search
            results = self.fred.search(search_query)
            
            if results is None or results.empty:
                print("❌ No matching series found.")
                return pd.DataFrame()
            
            # --- CRITICAL FILTERS TO ESCAPE THE FRED TRAP ---
            current_year = datetime.now().year
            
            # 1. Must have observations ending in the current calendar cycle (live data)
            active_mask = pd.to_datetime(results['observation_end']).dt.year >= (current_year - 1)
            
            # 2. Filter out explicit keywords denoting dead series
            no_discontinued_mask = ~results['title'].str.contains("Discontinued|DISCONTINUED|Historical", case=False, na=False)
            if 'notes' in results.columns:
                no_discontinued_mask &= ~results['notes'].str.contains("discontinued", case=False, na=False)
                
            filtered_results = results[active_mask & no_discontinued_mask].copy()
            
            if filtered_results.empty:
                print("⚠️ Found series matches, but they are all dead or discontinued.")
                return pd.DataFrame()
            
            # Sort by popularity index so you get the benchmarks first
            filtered_results = filtered_results.sort_values(by='popularity', ascending=False)
            
            # Format output columns cleanly
            output_cols = ['id', 'title', 'frequency', 'units', 'observation_start', 'observation_end', 'popularity']
            clean_df = filtered_results[output_cols].head(limit).reset_index(drop=True)
            
            # Rename columns for presentation
            clean_df.columns = ['Ticker ID', 'Series Title', 'Freq', 'Units', 'Starts', 'Ends', 'Popularity']
            return clean_df
            
        except Exception as e:
            print(f"❌ Search Error: {e}")
            return pd.DataFrame()

# =====================================================================
# EXECUTION EXAMPLE
# =====================================================================
if __name__ == "__main__":
    # Use your live engine key
    API_KEY = "1f3befec93b6c68383d27f3b58cca038" 
    searcher = FredDataSearcher(API_KEY)
    
    # Example 1: Let's find valid Interest Rates for Japan
    japan_rates = searcher.find_tickers(keyword="inflation", country="Switzerland", limit=5)
    print("\n--- LIVE JAPAN INTEREST RATE TICKERS ---")
    print(japan_rates.to_string())
    
    # Example 2: Let's find clean Inflation (CPI) data for the United Kingdom
    uk_inflation = searcher.find_tickers(keyword="inflation", country="India", limit=5)
    print("\n--- LIVE UK CPI TICKERS ---")
    print(uk_inflation.to_string())
    
    searcher.find_tickers(keyword="gdp growth rate", country="Euro Area")
    print("\n--- LIVE UK CPI TICKERS ---")
    print(uk_inflation.to_string())
