import pandas as pd
import numpy as np
import scipy.stats as stats

def run_continuous_sigma_test(csv_path, sigma_thresholds=[1.0, 2.0, 3.0]):
    print(f"Loading data from: {csv_path}")
    raw_df = pd.read_csv(csv_path, sep=None, engine='python')
    
    # Structural positional mapping
    df = pd.DataFrame()
    df['Date_Raw'] = raw_df.iloc[:, 0].astype(str)
    df['Time_Raw'] = raw_df.iloc[:, 1].astype(str)
    df['Open'] = raw_df.iloc[:, 2].astype(float)
    df['Close'] = raw_df.iloc[:, 5].astype(float)

    # Clean date and create a continuous chronological datetime index
    df['Clean_Date'] = df['Date_Raw'].str.replace('.', '-', regex=False)
    df['Timestamp'] = pd.to_datetime(df['Clean_Date'] + ' ' + df['Time_Raw'])
    df = df.sort_values(by='Timestamp').reset_index(drop=True)
    
    # 1. Calculate returns for EVERY bar in the dataset
    df['Bar_Return'] = (df['Close'] - df['Open']) / df['Open']
    
    # 2. Get the next bar's return (shifting backwards so "Next_Bar_Return" aligns with the current row)
    df['Next_Bar_Return'] = df['Bar_Return'].shift(-1)
    
    # Drop the very last row since it won't have a "next" bar
    df = df.dropna().reset_index(drop=True)
    
    # 3. Establish the global baseline volatility (Sigma) across ALL bars
    global_std = df['Bar_Return'].std()
    avg_price = df['Open'].mean()
    
    print("\n" + "="*60)
    print(f"   CONTINUOUS MAGNITUDE EXHAUSTION TEST (ALL BARS)")
    print("="*60)
    print(f"Total bars analyzed: {len(df)}")
    print(f"Global 1-Sigma baseline (Percentage): {global_std*100:.3f}%")
    print(f"Approx. 1-Sigma move at average price ({avg_price:.2f}): ±{avg_price * global_std:.4f} points")
    
    # Baseline background correlation for all bars
    r_all, p_all = stats.pearsonr(df['Bar_Return'], df['Next_Bar_Return'])
    print(f"\n[BACKGROUND] Overall Bar vs Next Bar Correlation: r = {r_all:.4f} (p-value: {p_all:.4f})")
    
    # 4. Iterate through your requested Sigma thresholds
