COLUMN_NAMES = [
    "Country",
    "GDP",
    "GDP_Growth",
    "Interest_Rate",
    "Inflation_Rate",
    "Unemployment_rate",
    "Gov_Budget",
    "Gov_Debt_to_GDP",
    "Population",
    "Current_Account_to_GDP"
]

print("[+] Attempting to read table data from your clipboard...")

try:
    # 2. Read clipboard, explicitly telling pandas NOT to look for a header row,
    # and assigning our custom column names instead.
    df_raw = pd.read_clipboard(header=None, names=COLUMN_NAMES)

    # 3. Clean up the Country column to remove any stray whitespace
    df_raw["Country"] = df_raw["Country"].str.strip()

    # 4. Set Country as the index so we can look up data cross-sectionally
    df_matrix = df_raw.set_index("Country")

    print("[+] Success! Data loaded into 'df_matrix'.")
    display(df_matrix.head(10))

except Exception as e:
    print(f"[!] Error: Could not parse clipboard. Did you copy the data row text?")
    print(f"Details: {e}")
