import project_pkg.filters_2 as filt
# Dictionary to hold the final cockpit rows for reporting
dashboard_records = []

fin_res = res1 | res2
for name, df in fin_res.items():
    try:
        # 1. Run the master matrix calculator on the symbol's dataframe
        processed_df = filt.build_confluence_matrix(df)
        
        # 2. Extract the latest available row (today's live state)
        # Drop rows where Hurst or MAs are still warming up
        valid_rows = processed_df.dropna()
        
        if valid_rows.empty:
            print(f"⚠️ [Skipping {name}]: Insufficient historical data to warm up Hurst/MAs.")
            continue
            
        latest_live_row = valid_rows.iloc[-1]
        
        # 3. Determine Human-Readable Action Rules based on Domain Pairings
        trend = latest_live_row["SCORE_TREND"]
        mom = latest_live_row["SCORE_MOMENTUM"]
        vol = latest_live_row["SCORE_VOLUME"]
        volat = latest_live_row["SCORE_VOLATILITY"]
        
        # Logic Routing Engine
        if trend > 50 and vol > 30:
            action = "Long"
        elif trend < -50 and vol > 30:
            action = "Short"
        elif trend < -40 and mom > 40 and volat < -30:
            action = "Long_v2"
        elif trend > 40 and mom < -40 and vol < -20:
            action = "Short_v2"
        elif abs(trend) < 20 and abs(mom) < 20 and vol < -10:
            action = "No"
        else:
            action = "No"
            
        # 4. Pack the structural data row into our master database
        dashboard_records.append({
            "Symbol": name,
            "Spot Price": latest_live_row["<CLOSE>"],
            "Trend Score": trend,
            "Momentum Score": mom,
            "Volume Score": vol,
            "Volatility/Regime": volat,
            "Engine Action": action,
            "As Of Date": latest_live_row["<DATE>"].strftime("%Y-%m-%d")
        })
        
#         print(f"✅ Processed {name.ljust(8)} | Date: {latest_live_row['<DATE>'].strftime('%Y-%m-%d')} | Price: ${latest_live_row['<CLOSE>']:,.2f}")
        
    except Exception as e:
        print(f"❌ [Error processing {name}]: {str(e)}")

# #Final results
if dashboard_records:
    master_dashboard_df = pd.DataFrame(dashboard_records)
