import pandas as pd
import numpy as np
import scipy.stats as stats

def run_weekly_reversion_test(csv_path, sigma_threshold=1.0):
    """
    Evaluates weekly cycles using daily data. Identifies extreme moves in the 
    early-to-mid week (Days 1-3) and tests for intra-week mean reversion, 
    as well as follow-through/reversion into the subsequent week.
    """
    print(f"Loading daily data from: {csv_path}")
    raw_df = pd.read_csv(csv_path, sep=None, engine='python')
    
    # 1. Structural Mapping & Chronological Sorting
    df = pd.DataFrame()
    df['Date_Raw'] = raw_df.iloc[:, 0].astype(str)
    df['Open'] = raw_df.iloc[:, 2].astype(float)
    df['Close'] = raw_df.iloc[:, 5].astype(float)
    
    df['Clean_Date'] = df['Date_Raw'].str.replace('.', '-', regex=False)
    df['Date'] = pd.to_datetime(df['Clean_Date'])
    df = df.sort_values(by='Date').reset_index(drop=True)
    
    # 2. Extract Calendar Identifiers for Weekly Grouping
    # ISO week allows us to group days belonging to the same calendar week
    df['Year'] = df['Date'].dt.isocalendar().year
    df['Week'] = df['Date'].dt.isocalendar().week
    df['Day_of_Week'] = df['Date'].dt.dayofweek # 0=Monday, 4=Friday
    
    # Calculate daily returns
    df['Daily_Return'] = (df['Close'] - df['Open']) / df['Open']
    
    # 3. Vectorized Intra-week Extraction
    # Enforce sequential ordering within each week
    df['Week_Day_Index'] = df.groupby(['Year', 'Week']).cumcount()
    
    # Pivot or group to isolate Day 1, Day 2, Day 3, and the Full Week Return
    weekly_grouped = df.groupby(['Year', 'Week'])
    
    weekly_data = []
    for (year, week), group in weekly_grouped:
        if len(group) >= 3:
            # Sort just to be absolutely sure
            group = group.sort_values('Date').reset_index(drop=True)
            
            d1_ret = group['Daily_Return'].iloc[0]
            d2_ret = group['Daily_Return'].iloc[1]
            d3_ret = group['Daily_Return'].iloc[2]
            
            # Contextual details for Day 2 (our extreme baseline target)
            d2_open = group['Open'].iloc[1]
            d2_abs_move = abs(group['Close'].iloc[1] - group['Open'].iloc[1])
            
            # Entire week performance (from first Open to last Close of the week)
            full_week_ret = (group['Close'].iloc[-1] - group['Open'].iloc[0]) / group['Open'].iloc[0]
            
            weekly_data.append({
                'Year': year,
                'Week': week,
                'Day1_Return': d1_ret,
                'Day2_Return': d2_ret,
                'Day3_Return': d3_ret,
                'Day2_Price_Level': d2_open,
                'Day2_Absolute_Move': d2_abs_move,
                'Current_Week_Return': full_week_ret
            })
            
    summary_df = pd.DataFrame(weekly_data)
    if len(summary_df) == 0:
        return None
        
    # 4. Map Next Week's Return (Shifted) to evaluate the following week's reversion
    summary_df['Next_Week_Return'] = summary_df['Current_Week_Return'].shift(-1)
    
    # Drop the last row since it won't have a 'Next Week' target
    summary_df = summary_df.dropna().reset_index(drop=True)
    
    # 5. Volatility Analysis (Baseline on Day 2 of the week)
    day2_std = summary_df['Day2_Return'].std()
    threshold_pct = sigma_threshold * day2_std
    
    # Dynamic point translation (fixes the recency bias from the previous version)
    summary_df['Day2_Threshold_Points'] = summary_df['Day2_Price_Level'] * threshold_pct
    
    # Segment regimes
    extreme_weeks = summary_df[summary_df['Day2_Return'].abs() > threshold_pct]
    normal_weeks = summary_df[summary_df['Day2_Return'].abs() <= threshold_pct]
    
    # --- METRICS & OUTPUTS ---
    print("\n" + "="*70)
    print(f"   WEEKLY CYCLE EXHAUSTION TEST (Threshold: {sigma_threshold} Sigma on Day 2)")
    print("="*70)
    print(f"Total baseline weeks: {len(summary_df)}")
    print(f"Extreme Day 2 weeks isolated: {len(extreme_weeks)} ({len(extreme_weeks)/len(summary_df)*100:.1f}% of data)")
    
    print(f"\n[VOLATILITY STATS]")
    print(f" -> Day 2 Baseline Volatility (Standard Deviation): {day2_std*100:.3f}%")
    print(f" -> Current Threshold Target: {threshold_pct*100:.3f}%")
    
    if len(extreme_weeks) > 5:
        print(f"\n[1] INTRA-WEEK REVERSION (Day 2 vs Day 3)")
        r_d23, p_d23 = stats.pearsonr(extreme_weeks['Day2_Return'], extreme_weeks['Day3_Return'])
        rev_rate_d3 = (((extreme_weeks['Day2_Return'] > 0) & (extreme_weeks['Day3_Return'] < 0)) | \
                       ((extreme_weeks['Day2_Return'] < 0) & (extreme_weeks['Day3_Return'] > 0))).mean() * 100
        print(f" -> Correlation: r = {r_d23:.4f} (p-value: {p_d23:.4f})")
        print(f" -> Day 3 Reversion Win-Rate: {rev_rate_d3:.2f}%")
        
        print(f"\n[2] FOLLOWING-WEEK REVERSION (Day 2 Move vs Next Week's Total Return)")
        r_next, p_next = stats.pearsonr(extreme_weeks['Day2_Return'], extreme_weeks['Next_Week_Return'])
        rev_rate_next = (((extreme_weeks['Day2_Return'] > 0) & (extreme_weeks['Next_Week_Return'] < 0)) | \
                        ((extreme_weeks['Day2_Return'] < 0) & (extreme_weeks['Next_Week_Return'] > 0))).mean() * 100
        print(f" -> Correlation: r = {r_next:.4f} (p-value: {p_next:.4f})")
        print(f" -> Following Week Reversion Win-Rate: {rev_rate_next:.2f}%")
    else:
        print("\n[!] INSIGNIFICANT SAMPLE: Too few weeks met the extreme criteria.")
        
    return summary_df

for currency in filtered_df['Currency']:
    file_path_h4 = fr"C:\Users\nitis\Documents\Forex\Data\New data\{currency}.csv"
    run_extreme_magnitude_test(file_path_h4, sigma_threshold=1.0)
