import pandas as pd
import numpy as np
import scipy.stats as stats

def run_weekly_reversion_test(csv_path, sigma_threshold=1.0):
    print(f"Loading daily data from: {csv_path}")
    raw_df = pd.read_csv(csv_path, sep=None, engine='python')
    
    # 1. Structural Mapping & Chronological Sorting
    df = pd.DataFrame()
    df['Date_Raw'] = raw_df.iloc[:, 0].astype(str)
    df['Open'] = raw_df.iloc[:, 2].astype(float)
    df['Close'] = raw_df.iloc[:, 5].astype(float)
    
    df['Clean_Date'] = df['Date_Raw'].str.replace('.', '-', regex=False)
    df['Date'] = pd.to_datetime(df['Clean_Date'])
    df = df.sort_values(by='Date').reset_index(drop=True)
    
    # Deduplicate by date just in case the source file has repeating rows
    df = df.drop_duplicates(subset=['Date']).reset_index(drop=True)
    
    # 2. Extract Exact Day of Week and Calendar Week
    df['Year'] = df['Date'].dt.isocalendar().year
    df['Week'] = df['Date'].dt.isocalendar().week
    df['Day_of_Week'] = df['Date'].dt.dayofweek # 0=Monday, 1=Tuesday, 2=Wednesday, etc.
    
    # Calculate daily returns properly as a decimal (e.g., 0.01 for 1%)
    df['Daily_Return'] = (df['Close'] - df['Open']) / df['Open']
    
    # 3. Pivot the data so each row represents EXACTLY one unique week
    # This completely removes the risky loop slicing
    pivoted = df.pivot(index=['Year', 'Week'], columns='Day_of_Week', values=['Daily_Return', 'Open', 'Close'])
    
    # Flatten the multi-index columns for clean access
    pivoted.columns = [f"{col[0]}_Day_{col[1]}" for col in pivoted.columns]
    pivoted = pivoted.reset_index()
    
    # Map out our targeted days explicitly by calendar day index
    # Day 0 = Mon, Day 1 = Tue, Day 2 = Wed
    weekly_df = pd.DataFrame()
    weekly_df['Year'] = pivoted['Year']
    weekly_df['Week'] = pivoted['Week']
    weekly_df['Day1_Return'] = pivoted['Daily_Return_Day_0'] # Monday
    weekly_df['Day2_Return'] = pivoted['Daily_Return_Day_1'] # Tuesday
    weekly_df['Day3_Return'] = pivoted['Daily_Return_Day_2'] # Wednesday
    weekly_df['Day2_Price_Level'] = pivoted['Open_Day_1']
    
    # Calculate whole-week return: From Monday's Open to Friday's Close (Day 4)
    # If Friday is missing, fallback to Thursday (Day 3)
    mon_open = pivoted['Open_Day_0']
    fri_close = pivoted['Close_Day_4'].fillna(pivoted['Close_Day_3'])
    weekly_df['Current_Week_Return'] = (fri_close - mon_open) / mon_open
    
    # Drop weeks where our core test days (Tue/Wed) are missing
    weekly_df = weekly_df.dropna(subset=['Day2_Return', 'Day3_Return']).reset_index(drop=True)
    
    # 4. Map Next Week's Return
    weekly_df['Next_Week_Return'] = weekly_df['Current_Week_Return'].shift(-1)
    weekly_df = weekly_df.dropna(subset=['Next_Week_Return']).reset_index(drop=True)
    
    # 5. Volatility Analysis
    day2_std = weekly_df['Day2_Return'].std()
    threshold_pct = sigma_threshold * day2_std
    
    # Segment regimes
    extreme_weeks = weekly_df[weekly_df['Day2_Return'].abs() > threshold_pct]
    normal_weeks = weekly_df[weekly_df['Day2_Return'].abs() <= threshold_pct]
    
    # --- METRICS & OUTPUTS ---
    print("\n" + "="*70)
    print(f"   FIXED WEEKLY CYCLE EXHAUSTION TEST (Threshold: {sigma_threshold} Sigma)")
    print("="*70)
    print(f"Total baseline weeks: {len(weekly_df)}")
    print(f"Extreme Day 2 weeks isolated: {len(extreme_weeks)} ({len(extreme_weeks)/len(weekly_df)*100:.1f}% of data)")
    
    print(f"\n[VOLATILITY STATS]")
    print(f" -> Day 2 (Tuesday) Volatility (Std Dev): {day2_std*100:.3f}%")
    print(f" -> Sigma Threshold (Percentage):          {threshold_pct*100:.3f}%")
    
    if len(extreme_weeks) > 5:
        print(f"\n[1] INTRA-WEEK REVERSION (Tuesday vs Wednesday)")
        r_d23, p_d23 = stats.pearsonr(extreme_weeks['Day2_Return'], extreme_weeks['Day3_Return'])
        rev_rate_d3 = (((extreme_weeks['Day2_Return'] > 0) & (extreme_weeks['Day3_Return'] < 0)) | \
                       ((extreme_weeks['Day2_Return'] < 0) & (extreme_weeks['Day3_Return'] > 0))).mean() * 100
        print(f" -> Correlation: r = {r_d23:.4f} (p-value: {p_d23:.4f})")
        print(f" -> Wednesday Reversion Win-Rate: {rev_rate_d3:.2f}%")
        
        print(f"\n[2] FOLLOWING-WEEK REVERSION (Tuesday Move vs Next Week's Return)")
        r_next, p_next = stats.pearsonr(extreme_weeks['Day2_Return'], extreme_weeks['Next_Week_Return'])
        rev_rate_next = (((extreme_weeks['Day2_Return'] > 0) & (extreme_weeks['Next_Week_Return'] < 0)) | \
                        ((extreme_weeks['Day2_Return'] < 0) & (extreme_weeks['Next_Week_Return'] > 0))).mean() * 100
        print(f" -> Correlation: r = {r_next:.4f} (p-value: {p_next:.4f})")
        print(f" -> Following Week Reversion Win-Rate: {rev_rate_next:.2f}%")
    else:
        print("\n[!] INSIGNIFICANT SAMPLE: Not enough extreme weeks match this criteria.")
        
    return weekly_df

for currency in filtered_df['Currency']:
    file_path_h4 = fr"C:\Users\nitis\Documents\Forex\Data\New data\{currency}.csv"
    run_weekly_reversion_test(file_path_h4, sigma_threshold=1.0)
