if os.path.exists(db_path):
    con = sqlite3.connect(db_path)
    cursor = con.cursor()
    
    # Search for any executed line containing your missing file's name
    search_term = '%dld_h4%'
    cursor.execute("SELECT session, line, source FROM history WHERE source LIKE ?", (search_term,))
    
    rows = cursor.fetchall()
    
    if rows:
        print(f"--- FOUND {len(rows)} MATCHES IN YOUR IPYTHON HISTORY ---\n")
        for row in rows:
            print(f"Session {row[0]}, Line {row[1]}:")
            print(row[2])
            print("-" * 50)
    else:
        print("No exact matches for 'dld_h4' found in the history text.")
        print("Let's look for any 'def ' statements you might have run:")
        
        # Backup search: look for any function definitions that might have been pasted/run
        cursor.execute("SELECT source FROM history WHERE source LIKE '%def %' ORDER BY session DESC LIMIT 50")
        def_rows = cursor.fetchall()
        for r in def_rows:
            print(r[0])
            print("-" * 50)
            
    con.close()
else:
    print(f"Could not locate the history database at {db_path}")
